contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Read the caller's balance before any state change via the public getter.
        uint beforeBalance = c.getBalance(address(this));
        uint beforeContractEther = address(c).balance;

        // Fund this test contract with the deposit amount (accounting for msg.value).
        c.addToBalance{value: depositAmount}();

        uint afterDepositBalance = c.getBalance(address(this));
        uint afterDepositContractEther = address(c).balance;

        // Attempt a withdrawal with the given withdrawAmount parameter; the parameter
        // only controls the call count/context, not the withdrawn amount (which is fixed by state).
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read state after the withdrawal attempt.
        uint afterBalance = c.getBalance(address(this));
        uint afterContractEther = address(c).balance;

        // General rule: a failed withdrawal leaves the caller's recorded balance and the
        // contract's Ether balance exactly as they were immediately before the withdrawal.
        // A successful withdrawal can only decrease the caller's recorded balance and the
        // contract's Ether balance, never increase them.
        if (reverted) {
            assert(afterBalance == afterDepositBalance);
            assert(afterContractEther == afterDepositContractEther);
        } else {
            assert(afterBalance <= afterDepositBalance);
            assert(afterContractEther <= afterDepositContractEther);
        }
    }

    receive() external payable {}
}
